mapper.sql:
replay_list_dedup AS ( SELECT DISTINCT ON (rid) rid, wizard_id, win_lose, date_add FROM ranker_rtpvp_replay_list WHERE 1 = 1
AND date_add >= #{seasonStart} AND date_add < #{seasonEnd}
ORDER BY rid, crt_date DESC NULLS LAST )

mapper.select:
SELECT MIN(r.date_add)::date AS min_date, MAX(r.date_add)::date AS max_date FROM ( SELECT DISTINCT ON (rid) rid, date_add FROM ranker_rtpvp_replay_list WHERE 1 = 1
AND date_add >= #{seasonStart} AND date_add < #{seasonEnd}
ORDER BY rid, crt_date DESC NULLS LAST ) r

mapper.update:
UPDATE ranker_rtpvp_replay_list
SET synergy_agg_status = 'failed'
WHERE rid = #{rid}

mapper.select:
SELECT COUNT(*)::int
FROM rta_summoner_ranking_agg
WHERE season_code = #{seasonCode}
